select plan_id
from fx67ll_dortmund_plan_return_rel
where combination_id = #{combinationId}

select rel_id, plan_id, combination_id, rel_sort, create_by, create_time, update_by, update_time from fx67ll_dortmund_plan_return_rel where plan_id in
#{planId}
order by plan_id, case when rel_sort is null or rel_sort = 0 then 1 else 0 end asc, case when rel_sort is null or rel_sort = 0 then 0 else rel_sort end asc, STR_TO_DATE(create_time, "%Y-%m-%d %H:%i:%s") desc, rel_id desc
